/* Local jQuery loader (loads CDN if not already present).
   This file intentionally bootstraps jQuery from the official CDN so pages
   that include this local file get a working $/jQuery symbol even if the
   real minified file wasn't checked into the repo. If you want a truly
   offline/local copy, replace this file's contents with the official
   minified jQuery source from https://code.jquery.com/jquery-4.0.0.min.js
*/
(function () {
  if (window.jQuery) return;
  var s = document.createElement('script');
  s.src = 'https://code.jquery.com/jquery-4.0.0.min.js';
  s.integrity = '';
  s.crossOrigin = 'anonymous';
  s.onload = function () { console.info('jQuery loaded (CDN)'); };
  s.onerror = function () { console.warn('Failed to load jQuery from CDN'); };
  document.head.appendChild(s);
})();
